#include "runtime/interpreter.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace penta;
int main(){
    int failures=0;auto expect=[&](bool okay,const char* message){if(!okay){++failures;std::cerr<<message<<'\n';}};
    const std::string source="% Unicode Î»\nfunction real inner(real x){return sqrt(-x);}\nfunction real outer(real x){return inner(x);}\nreal y=outer(2);";
    language::AnalysisOptions options;options.sourceIdentity="/test/main.p";
    const auto result=runtime::execute(source,options);expect(!result.ok()&&result.analysis.ok(),"Nested runtime failure remains a runtime diagnostic.");
    if(!result.runtimeDiagnostics.empty()){const auto& diagnostic=result.runtimeDiagnostics.front();expect(diagnostic.frames.size()==2,"Nested failure retains both callee frames.");if(diagnostic.frames.size()==2){expect(diagnostic.frames[0].function=="inner"&&diagnostic.frames[1].function=="outer","Call frames retain innermost-to-outermost order.");expect(diagnostic.frames[0].sourceIdentity==options.sourceIdentity,"Retained source identity is exact.");expect(diagnostic.frames[0].source&&*diagnostic.frames[0].source==source,"Frame retains the original immutable source bytes.");expect(diagnostic.frames[0].sourceHash.size()==64,"Frame includes a source fingerprint.");expect(language::sourceLocation(source,diagnostic.frames[0].span.offset).line==2,"Original failure span locates the inner body.");expect(language::sourceLocation(source,diagnostic.span.offset).line==4,"Primary diagnostic retains the invocation line.");}}
    runtime::InterpreterSession session;const std::string prior="function real earlier(real x){return sqrt(-x);};";options.sourceIdentity="/test/earlier.p";expect(session.submit(prior,options).ok(),"Earlier function definition is retained.");options.sourceIdentity="<command>";const auto later=session.submit("earlier(2)",options);expect(!later.ok()&&!later.runtimeDiagnostics.empty(),"Later call reports the retained function failure.");if(!later.runtimeDiagnostics.empty()){const auto& frames=later.runtimeDiagnostics.front().frames;expect(frames.size()==1&&frames[0].sourceIdentity=="/test/earlier.p"&&frames[0].source&&*frames[0].source==prior,"Earlier-source coordinates are never remapped into the new command.");}
    const auto directory=std::filesystem::temp_directory_path()/("penta-frame-test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(directory);std::ofstream(directory/"helper.p",std::ios::binary)<<"% Imported body\r\nfunction real bad(real x){return sqrt(-x);}\r\n";options.sourceDirectory=directory;options.sourceIdentity=(directory/"main.p").generic_string();
    const auto imported=runtime::execute("import \"helper.p\" as tools;real y=tools.bad(2);",options);expect(!imported.ok()&&!imported.runtimeDiagnostics.empty(),"Imported callee failures remain observable.");if(!imported.runtimeDiagnostics.empty()){const auto& frames=imported.runtimeDiagnostics.front().frames;expect(!frames.empty()&&frames.front().sourceIdentity.find("helper.p")!=std::string::npos,"Imported frame identifies the defining module.");}
    runtime::ExecutionOptions nativeOptions;nativeOptions.dataDirectory=directory;nativeOptions.odeCacheDirectory=directory/"odes";options.sourceIdentity=(directory/"native.p").generic_string();
    const auto odeFailed=runtime::execute("ode bad_rhs(t,real x){x'=sqrt(-x);};solution s=odesolve(bad_rhs,x=1,t0=0,t1=0);",options,nativeOptions);expect(!odeFailed.ok()&&!odeFailed.runtimeDiagnostics.empty(),"Native ODE failure remains observable.");if(!odeFailed.runtimeDiagnostics.empty()){const auto& frames=odeFailed.runtimeDiagnostics.front().frames;expect(!frames.empty()&&frames[0].function=="bad_rhs"&&frames[0].sourceHash.size()==64,"Native ODE DLL failure retains its defining source frame.");}
    const auto callbackFailed=runtime::execute("native function real bad_callback(real x){return sqrt(-x);}real y=bad_callback(2);",options,nativeOptions);expect(!callbackFailed.ok()&&!callbackFailed.runtimeDiagnostics.empty(),"Direct native failure remains observable.");if(!callbackFailed.runtimeDiagnostics.empty()){const auto& frames=callbackFailed.runtimeDiagnostics.front().frames;expect(!frames.empty()&&frames[0].function=="bad_callback","Direct native DLL failure retains its source frame.");}
    std::error_code ignored;std::filesystem::remove_all(directory,ignored);std::cout<<failures<<" source-frame failures\n";return failures?1:0;
}
